The following Python program was run on the graph with vertices 1 to 6 and adjacency lists 1: 2, 3; 2: 1, 3; 3: 1, 2, 4; 4: 3, 5, 6; 5: 4, 6; 6: 4, 5. Its first two printed lines are wanted.
```
from collections import deque

ADJ = {1: [2, 3], 2: [1, 3], 3: [1, 2, 4], 4: [3, 5, 6], 5: [4, 6], 6: [4, 5]}

def bfs(adj, s):
    dist = {s: 0}
    order = [s]
    q = deque([s])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                order.append(v)
                q.append(v)
    return dist, order

def dfs(adj, s):
    seen, out = set(), []
    def go(u):
        seen.add(u)
        out.append(u)
        for v in adj[u]:
            if v not in seen:
                go(v)
    go(s)
    return out

print(bfs(ADJ, 1))
print(dfs(ADJ, 1))
```
