A routine is meant to build a minimum spanning tree by taking edges in increasing order of weight and keeping those that join two different pieces.
```
def kruskal(W):
    parent = {v: v for v in W}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    edges = sorted({(min(u, v), max(u, v), w) for u in W for v, w in W[u].items()})
    total, used = 0, []
    for u, v, w in edges:
        if find(u) != find(v):
            parent[find(u)] = find(v)
            total += w
            used.append((u, v, w))
    return total, used

W = {1: {2: 4, 3: 2, 6: 10}, 2: {1: 4, 3: 1, 4: 5},
     3: {1: 2, 2: 1, 4: 8, 6: 3}, 4: {2: 5, 3: 8, 5: 3, 6: 2},
     5: {4: 3, 6: 1}, 6: {1: 10, 3: 3, 4: 2, 5: 1}}
print(kruskal(W)[0])
```
